"""Ticket state machine."""

KNOWN_STATES = {"new", "open", "closed"}


class BadTransition(Exception):
    pass


class Ticket:
    def __init__(self, state="new"):
        if state not in KNOWN_STATES:
            raise ValueError("unknown state")
        self.state = state

    def move_to(self, new_state):
        if new_state not in KNOWN_STATES:
            raise ValueError("unknown state")
        self.state = new_state
        return self.state

